const body = $json.body ?? $json;
const params = body.params ?? {};
const recipientIds = Array.isArray(params.recipient_ids) ? params.recipient_ids.map(String).filter(Boolean) : [];
if (!recipientIds.length) {
  throw new Error('recipient_ids is empty');
}
return [{
  json: {
    org_uid: body.org_uid,
    action_code: body.action_code,
    role: body.role ?? null,
    client_time: body.client_time ?? null,
    campaign_name: params.campaign_name || 'Telegram campaign',
    segment: params.segment || 'Все клиенты',
    text: params.text || '',
    filters: params.filters || {},
    recipients_count: Number(params.recipients_count || recipientIds.length),
    recipient_ids: recipientIds,
    transport: params.transport || 'telegram'
  }
}];

const campaign = $('Normalize Request').first().json;
const rows = items.map(item => item.json);
const valid = rows.filter(row => row.tg_username);
if (!valid.length) {
  return [{ json: { ...campaign, sent: 0, skipped: campaign.recipient_ids.length, recipients: [] } }];
}
return valid.map((row) => ({
  json: {
    ...campaign,
    tg_id: String(row.tg_id),
    tg_username: row.tg_username.startsWith('@') ? row.tg_username : `@${row.tg_username}`,
    telegram_chat_id: row.tg_id,
    client_name: row.name || [row.first_name, row.last_name].filter(Boolean).join(' ') || 'Клиент'
  }
}));

const campaign = $('Normalize Request').first().json;
const sentItems = items.filter(item => !item.json.error);
const failedItems = items.filter(item => item.json.error);
return [{
  json: {
    ok: failedItems.length === 0,
    action_code: campaign.action_code,
    campaign_name: campaign.campaign_name,
    transport: 'telegram',
    requested_recipients: campaign.recipients_count,
    resolved_recipients: items.length,
    sent_count: sentItems.length,
    failed_count: failedItems.length,
    failed: failedItems.map(item => ({ recipient: item.json.tg_username || item.json.telegram_chat_id, error: item.json.error }))
  }
}];
